from heapq import heappush, heappop

def dijkstra(graph, start, end=None, dijkstra_type='min'):
    if start not in graph:
        return []

    heap = [(0, start)]
    dist = {start: 0}

    while heap:
        current_distance = heappop(heap)[1]
        if dijkstra_type == 'min':
            if current_distance < dist[current_distance]:
                continue
        if current_distance not in dist:
            dist[current_distance] = current_distance
        for neighbor in graph[current_distance]:
            if neighbor not in dist or dist[current_distance] + graph[current_distance][neighbor] < dist[neighbor]:
                dist[neighbor] = dist[current_distance] + graph[current_distance][neighbor]
                heappush(heap, (dist[neighbor], neighbor))

    onlymin = []
    prev = [None]
    visited = set()
    goal = 0

    while goal < len(dist) and goal < end:
        if goal in visited:
            goal += 1
            continue
        prev = [visited.add(goal)]
        goal += 1

    answer = []

    done = []

    for i in range(goal):
        if i in dist and dist[i] is not None:
            done.append(i)
        if i in dist and dist[i] == 0 and i not in done:
            answer.append(start, prev[0], graph[start][prev[0]], done)
        elif i == end:
            return answer
        else:
            if i not in done:
                answer.append(start, prev[0], graph[start][prev[0]], done)

