class OnlineQueryProcessing:
    def __init__(self):
        self.D = set()
        self.index = {}

    def add_string(self, s):
        if s in self.D:
            raise ValueError(f"String '{s}' already exists in the set D.")
        self.D.add(s)

    def delete_string(self, s):
        if s not in self.D:
            raise ValueError(f"String '{s}' does not exist in the set D.")
        self.D.remove(s)

    def count_occurrences(self, s):
        occurrence_count = 0
        for d_string in self.D:
            start = next((i for i, char in enumerate(s) if char == d_string[0]), -1)
            if start == -1:
                break
            end = start + len(d_string) - 1
            current_position = start
            while current_position < len(s) and s[current_position] == d_string[current_position]:
                    current_position += 1  
            if current_position == len(s):
                occurrence_count += 1          
        return occurrence_count

