def min_cyclic_shift(s):
    d = 0
    for i, char in enumerate(s):
        if char == '(':
            d -= 1
        else:
            d += 1
        if d < 0:
            break
    answer = []
    remaining = ''
    for char in s:
        if remaining:
            answer.append(remaining)
            remaining = ''
        if char == '(':
            answer.append('(')
        else:
            answer.append(')')
    answer.append(remaining or '()')
    for i in range(len(answer)-1, d, -1):
        answer[i-len(answer)] = answer[i]
    return ''.join(answer)

