def count_triangles(n, points):
    if n <= 3:
        return 0

    def cross(a, b):
        x1, y1 = b
        x2, y2 = a
        return x1 * y2 - x2 * y1

    def in_triangle(a, b, c):
        area1 = cross(a, b) * cross(a, c)
        area2 = cross(b, c) * cross(b, a)
        area3 = cross(c, a) * cross(c, b)
        return abs(area1 + area2 + area3) % 1000000007 == 0

    def get_triangle_areas(points):
        triangles = []
        n = len(points)
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    if in_triangle(points[i], points[j], points[k]):
                        triangles.append((points[i], points[j], points[k]))
        return triangles

    points.sort()
    triangles = get_triangle_areas(points)
    return len(triangles)

