    else:
        return min(10*red_count, 10*blue_count)

def bipartite_coloring(n1: int, n2: int, edges: List[Tuple[int, int]]) -> str:
    graph = defaultdict(dict)
    for u, v in edges:
        graph[u][v] = graph[v][u] = True

    for v, red_v in graph.items():
        red_edges = { w for w in graph[v] if graph[v][w] }
        blue_edges = { w for w in graph[v] if w not in red_v }
        if len(red_v) < len(blue_edges):
            add_red = len(blue_edges) - len(red_v)
        else:
            add_blue = len(red_v) - len(blue_edges)
        total_cost = add_blue * 15 + add_red * 15
        if red_count < add_red:
            total_cost += add_red
        elif blue_count < add_blue:
            total_cost += add_blue
        total_cost += calculate_cost(red_count, blue_count)
        if red_count < add_red:
            red_count += add_red
        elif blue_count < add_blue:
            blue_count += add_blue
        if total_cost > cost:
            return -1

    return (10000000 if cost == -1 else cost), "".join(["B" if graph[u][v] else "U" for u, v in edges])

