                start, end = road
                if start == from_city and end == current_city:
                    # Mark current_city as visited and try computing new distance using the flag at current_city
                    visited[current_city - 1] = 1
                    current_distance = new_flags[current_city - 1]
                    distance_to_target = sys.maxsize
                    for derived_distance, path in compute_distance_and_route(end, current_city, visited, path):
                        distance_to_target = min(distance_to_target, current_distance + derived_distance)
                    visited[current_city - 1] = 0
                elif end == from_city and start == current_city:
                    # Use conditional visitation of the cities to make sure start and end are not visited simultaneously
                    if visited[current_city - 1] == 0:
                        # Mark current_city as visited and try computing new distance using the flag at current_city
                        current_distance = new_flags[current_city - 1]
                        distance_to_target = sys.maxsize
                        for derived_distance, path in compute_distance_and_route(start, current_city, visited, path):
                            distance_to_target = min(distance_to_target, current_distance + 2*derived_distance)
                    else:
                        distance_to_target = current_distance + new_flags[current_city - 1]
                visited[current_city - 1] = 0
            return distance_to_target, path
        return distance_to_target, path

    # Perform BFS for all starting cities
    for city in range(n):
