class BracketSequence:
    def __init__(self, sequence):
        self.sequence = sequence

    def add_bracket(self, position, bracket):
        if position == 0:
            self.sequence = (bracket + self.sequence) if bracket == '(' else self.sequence + (bracket + '')
        elif position == len(self.sequence) - 1:
            self.sequence = self.sequence[:position] + (bracket,) + self.sequence[position:]
        else:
            self.sequence = (self.sequence[:position] + (bracket,) + self.sequence[position:]) if bracket == '(' else \
                (self.sequence[:position] + self.sequence[position:position + 1] + bracket +
                 self.sequence[position + 1:])

    def cyclic_shift(self, count):
        sequence_length = len(self.sequence)
        for _ in range(count % sequence_length):
            self.add_bracket(sequence_length, '(')

    def find_min_sequence(self, min_sequence):
        if not min_sequence or len(min_sequence) < len(self.sequence):
            return self.sequence
        for i in range(len(self.sequence) + 1):
            if i == len(min_sequence):
                continue
            modified_sequence = min_sequence[:i] + (self.sequence[i - 1],) + min_sequence[i:]
            modified_sequence_str = ''.join(modified_sequence)
            if modified_sequence_str < min_sequence:
                self.cyclic_shift(len(min_sequence) - len(self.sequence))
                return self.find_min_sequence(min_sequence)
        return self.sequence

