from itertools import permutations
from math import gcd

MOD = 10**9 + 7

def lcm(x, y):
    return x * y // gcd(x, y)

def inv(n):
    return pow(n, MOD-2, MOD)

def make_tangent(p1, p2):
    return (p2[0] - p1[0]) * lcm(2, 1 - gcd(p2[1] - p1[1], 1)), p2[1] - p2[0] * (p2[1] - p1[1]) // (p2[0] - p1[0])

def main(P):
    edges = list(map(make_tangent, list(permutations(P, 2))))

    for i, edge in enumerate(edges):
        A, B, C = edges[0], edges[i], edges[(i + 1) % len(edges)]
        if A[0] - B[0] == A[0] - C[0]:
            continue
        slope_A = A[1] - A[0] / A[0]
        slope_B = B[1] - B[0] / B[0]
        if slope_A == slope_B:
            return 0

    return sum(1 for edge in edges) % MOD

