import sys

class QueryProcessor:
    def __init__(self):
        self.string_map = {}
        self.counts = {}

    def process_query(self, t, s):
        if t == 1:
            self.add_string(s)
        elif t == 2:
            self.delete_string(s)
        elif t == 3:
            self.print_occurrences(s)
        else:
            raise ValueError("Invalid query type")

    def add_string(self, s):
        self.string_map[s] = True
        for char in s:
            if char in self.counts:
                self.counts[char] += 1
            else:
                self.counts[char] = 1

    def delete_string(self, s):
        self.string_map.pop(s, None)
        for char in s:
            self.counts[char] -= 1
            if self.counts[char] == 0:
                del self.counts[char]

    def print_occurrences(self, s):
        for char in s:
            if char in self.string_map:
                value = self.counts.pop(char, -1)
                if value != -1:
                    print(value)
                else:
                    print(0)

def main():
    processor = QueryProcessor()
    qq = int(input())
    for _ in range(qq):
        type, s = input().split()
        processor.process_query(int(type), s)

if __name__ == "__main__":
