from heapq import heappush, heappop

def add_brackets(s):
    nums, opened, closed = 0, 0, 0  # Number of opening and closing brackets
    opening_stack = []  # Stack to keep track of opening brackets

    for char in s:
        if char == '(':
            heappush(opening_stack, 'open')
        elif char in ('+', ')'):
            heappush(opening_stack, 'close')
        else:  # Closing bracket
            if heappop(opening_stack) == 'open':
                nums += 1

    # Push opening brackets to the end of the sequence for each closed bracket
    for _ in range(closed - 1):  
        heappush(opening_stack, 'open')

    # Push closing brackets to the end of the sequence
    for _ in range(nums - closed):
        heappush(opening_stack, 'close')

    # Separate opening and closing brackets
    while opening_stack:
        if opening_stack[0] == 'open' and nums:
            heappop(opening_stack)
            nums -= 1
        elif opening_stack[0] == 'open':
            heappop(opening_stack)
        elif opening_stack[0] == 'close':
            heappop(opening_stack)
        else:  # Skipped
            pass

    return ''.join(opening_stack)

