from math import comb
from functools import lru_cache

MOD = 10**9 + 7

def f(n, k):
    if k == 1:
        return 1
    if k == 2:
        return pow(2, pow(2, n-1), MOD)
    @lru_cache(None)
    def dp(i, prev):
        if k == i:
            return 1
        if i > n:
            return 0
        return sum(f(i+1, k-1) * comb(k-1, prev) for prev in range(1, k-1)) + sum(f(i+1, k-1) * comb(k-1, prev) for prev in range(i+1, k+1)) % MOD
