from operator import mod

class Query:
    def __init__(self, query_id, l, r, u, v):
        self.query_id = query_id
        self.l = l
        self.r = r
        self.u = u
        self.v = v

    def apply_transformation(self, mod):
        if self.r - self.l + 1 <= 1:
            if self.v - self.u + 1 == 0:
                return mod
            transformed_sum = 0
            for i in range(self.u, self.v + 1):
                transformed_sum += i
            return transformed_sum % mod
        else:
            odd_sum = 0
            even_sum = 0
            for i in range(self.l, self.r + 1):
                if i & 1:
                    odd_sum += i
                else:
                    even_sum += i
            return (self.apply_transformation(self.l - 1, self.u, mod) +
                    self.apply_transformation(self.v + 1, self.v, mod) + 
                    self.apply_transformation(self.v, self.v, mod) - 
                    self.apply_transformation(self.u - 1, self.u - 1, mod) +
                    even_sum + odd_sum) % mod

def process_queries(queries, mod):
    for query in queries:
        print(query.apply_transformation(mod), end=' ')
    print()

