def simulate_rotation(arc_positions, p_i):
    # Assume the arcs start at position 0 for simplicity
    n = len(arc_positions)
    ring_0_positions = list(range(n * n))
    for i in range(1, len(arc_positions) + 1):
        ring_idx = (i - 1) % n
        ring_positions = arc_positions[:n * n // n]  # Mirror positions for ring i
        for j in range(len(ring_positions)):
            ring_positions[j] += arc_positions[i - 1] * ring_idx
            ring_positions[j] %= n * n  # Wrap around positions for 0-indexed
        arc_positions[ring_idx - 1] = (n * n // n - len(ring_positions)), (n * n // n - len(ring_positions)) + 1 - max(range(len(ring_positions)))

    # Reverse the order since the mask started at the end
    arc_positions = arc_positions[::-1]

    for i in range(p_i):
        ring_position = arc_positions[0]
        arc_positions[0] += arc_positions[0]
        arc_positions[0] %= n * n
        arc_positions[n - 1], ring_position = ring_position, arc_positions[n - 1]

