def find_unique_periods(length, string):
    unique_periods = []
    unique_char_count = {}

    for i in range(length):
        if string[i] == '?':
            char = 'V'
        else:
            char = string[i]

        if char in unique_char_count:
            unique_char_count[char] += 1
        else:
            unique_char_count[char] = 1

        if len(unique_char_count) > 2:  # More than two unique characters, no repeating substring
            break

        periods = set()
        for period in range(1, length + 1):
            if string[i % period:i + length - period+1] == string[:length - period+1]:
                periods.add(period)

        unique_periods.append(min(periods, default=0))

    return len(unique_periods), sorted(unique_periods)

