def find_route(n, c, d, edges):
    # Check if the initial colors match the desired colors
    if all(c[i] == d[i] for i in range(n)):
        return "Yes", 0
    # Find the diameter of the tree
    degree = [0] * n
    for u, v in edges:
        degree[u-1] += 1
        degree[v-1] += 1
    diameter = 0
    for i in range(n):
        if degree[i] > degree[diameter]:
            diameter = i
    # Remap colors to reconstruct a Hamiltonian path
    color_remapping, remapped_c, remapped_d = [0]*n, [0]*n, [0]*n
    max_map = diameter
    for i in range(diameter):
        if c[i] == c[diameter + n - i - 1]:
            color_remapping[i] = max_map
        else:
            color_remapping[i] = max_map + 1
            max_map += 1
    # Try to remap the initial colors again
    for i in range(n):
        remapped_c[i] = c[color_remapping[i]]
    remapped_d = [remapped_c[i] for i in range((n-1)//2)]
    # Check if the remapped colors are the same as the desired colors
    if all(remapped_d[i] == remapped_d[i+1] for i in range(n-1)):
        return "Yes", n
    return "No"

