from collections import OrderedDict

class XORCache:
    def __init__(self):
        self.cache = OrderedDict()

    def get(self, x):
        try:
            return self.cache[x]
        except KeyError:
            return -1

    def update(self, l, r, x):
        l ^= self.get(l)
        r ^= self.get(r)
        self.cache = OrderedDict(sorted(self.cache.items()))
        cache_items = list(self.cache.items())
        if r < l:
            l, r = r, l
        if l <= r:
            if (l, x - l) not in self.cache:
                self.cache[x - l] = l
        else:
            cache_mid = (l + r) // 2
            while cache_mid >= l:
                if (cache_mid, x - cache_mid) not in self.cache:
                    self.cache[x - cache_mid] = cache_mid
                cache_mid //= 2

    def query(self, l, r):
        l ^= self.get(l)
        r ^= self.get(r)
        return self.get(l) ^ self.get(r)


def process_queries(N, P, queries):
    cache = XORCache()
    for t, l, r, x in queries:
        if t == 1:
            l ^= cache.get(l)
            r ^= cache.get(r)
            cache.update(l, r, x)
        else:
            x ^= cache.get(l)
            x ^= cache.get(r)
            print(-1 if x != cache.get(l) ^ cache.get(r) else cache.query(l, r))


if __name__ == "__main__":
